        h2: "Два паралельні шари: корпоративний і трудовий",
        html: `<p>Зміна директора — це дві різні процедури, які виконуються одночасно й часто плутаються в одну. Якщо зробити лише одну, виникають проблеми.</p>
<table>
<thead><tr><th>Шар</th><th>Що оформлюється</th><th>Наслідок</th></tr></thead>
<tbody>
<tr><td><b>Корпоративний</b></td><td>рішення учасників + реєстрація змін в ЄДР</td><td>повноваження представляти товариство перед третіми особами</td></tr>
<tr><td><b>Трудовий</b></td><td>накази про звільнення й про прийняття, запис у кадрових документах</td><td>трудові відносини, оплата праці, стаж</td></tr>
</tbody>
</table>
<p>Що буває, коли шари розсинхронізовані:</p>
<ul>
<li><b>рішення є, реєстрації немає</b> — у ЄДР досі старий директор, і банк, контрагенти та держоргани визнають повноваження за ним, а не за новим;</li>
<li><b>реєстрація є, наказів немає</b> — трудові відносини не оформлені, виникають питання з оплатою праці та звітністю;</li>
<li><b>звільнили старого, не призначили нового</b> — товариство залишається без керівника, що блокує будь-які дії від його імені.</li>
</ul>
<p>Тому правильна послідовність — не «спершу одне, потім інше», а один пакет документів, підготовлений разом.</p>`,
