<p>Практичне питання, яке виникає завжди: <strong>хто підписує наказ про звільнення директора</strong>. Відповідь залежить від ситуації — підписантом може бути новий керівник, уповноважена учасниками особа або сам керівник, якщо він ще не звільнений. Цей момент варто продумати до складання протоколу, а не в день підписання: протокол може прямо уповноважити конкретну особу на підписання кадрових документів, і це знімає питання.</p>
