<p>Про тридцятиденний строк варто сказати окремо. Обов'язок надати <b>обґрунтований розрахунок і копії документів</b> — це найсильніший інструмент колишнього учасника. Саме ці документи дають можливість перевірити оцінку, а їх ненадання є самостійним порушенням, з якого починається більшість спорів про вартість частки.</p>
