        id: "s4",
        h2: "Податки при продажу частки",
        html: `<p>Для фізичної особи продаж частки — операція з <b>інвестиційним активом</b>.</p>
<p>Оподатковується не вся сума, отримана від покупця, а <b>інвестиційний прибуток</b> — позитивна різниця між доходом від продажу корпоративних прав і <b>документально підтвердженими витратами</b> на їх придбання, зокрема на внесення коштів до статутного капіталу (пп. 14.1.81-1 ПКУ). Ставки:</p>
<ul>
<li><b>18 % ПДФО</b>;</li>
<li><b>5 % військового збору</b>;</li>
<li>разом — <b>23 %</b> від інвестиційного прибутку.</li>
</ul>
<p>Приклад. Учасник вніс до статутного капіталу 50 000 грн, продав частку за 1 200 000 грн:</p>
<ul>
<li>інвестиційний прибуток: 1 200 000 − 50 000 = <b>1 150 000 грн</b>;</li>
<li>ПДФО 18 %: <b>207 000 грн</b>; військовий збір 5 %: <b>57 500 грн</b>;</li>
<li>разом податків <b>264 500 грн</b>, на руки — <b>935 500 грн</b>.</li>
</ul>
<p>Три практичні моменти:</p>
<ul>
<li><b>Покупець не є податковим агентом.</b> Купуючи частку у фізичної особи, він <b>не зобов'язаний</b> утримувати ПДФО чи військовий збір — продавець рахує й сплачує сам. Покупці часто про це не знають і дарма резервують суму;</li>
<li><b>декларація</b> про майновий стан і доходи подається <b>до 1 травня</b> року, наступного за роком продажу, податок сплачується <b>до 1 серпня</b>;</li>
<li><b>без документів про витрати податок буде з усієї суми.</b> Платіжні документи про внесення вкладу, попередній договір купівлі-продажу частки, статут у редакції на момент внесення — усе це потрібно мати. Відтворити їх через 10 років ніде.</li>
</ul>
<p>Якщо продавець — <b>юридична особа</b>, результат від продажу корпоративних прав враховується у фінансовому результаті до оподаткування за загальними правилами податку на прибуток. Якщо покупець або продавець — <b>нерезидент</b>, додаються правила трансфертного ціноутворення й питання оподаткування доходів нерезидента з джерелом в Україні, і такі угоди потребують окремого аналізу до підписання.</p>`,
