        html: `<p>Корпоративний спір майже завжди дешевше попередити, ніж виграти: навіть виграна справа означає місяці публічного конфлікту, паралізовані рішення й зіпсовані відносини з банками та контрагентами.</p>
<ol>
<li><b>Статут під конкретну структуру власності</b>, а не модельний. Кваліфіковані більшості, перелік питань виключної компетенції зборів, порядок скликання й повідомлення, кворум, правила відчуження часток, доля частки при виході. Див. <a href="/blog/statut-tov/">статут ТОВ</a>.</li>
<li><b>Корпоративний договір</b> із механізмами виходу з патової ситуації, tag-along і drag-along, зобов'язаннями щодо голосування в межах закону. Див. <a href="/blog/korporatyvnyy-dohovir/">корпоративний договір</a>.</li>
<li><b>Документована процедура зборів.</b> Повідомлення з доказами надсилання, порядок денний, протокол. Два найчастіших безумовних порушення — рішення поза порядком денним і відсутність протоколу — усуваються простою дисципліною.</li>
<li><b>Межі повноважень директора</b> письмово: ліміти сум, перелік правочинів, що вимагають згоди, звітність.</li>
<li><b>Прозорий порядок розподілу прибутку</b> — більшість конфліктів починається саме з дивідендів. Див. <a href="/blog/dyvidendy-tov/">дивіденди ТОВ</a>.</li>
<li><b>Моніторинг ЄДР</b> і реєстраційні застереження — проти реєстраційних дій без вашої волі: див. <a href="/blog/zakhyst-vid-reyderstva/">захист від рейдерства</a>.</li>
<li><b>Фіксація домовленостей одразу</b>, а не «потім оформимо». Усна домовленість партнерів у корпоративному спорі не доводиться.</li>
</ol>
<p>І практичне: якщо конфлікт уже почався, перші дії зазвичай визначають результат. Варто одразу зафіксувати стан справ — витяг з ЄДР, копії статуту й протоколів, доступи, стан рахунків і майна — і <b>не вчиняти дій, які потім обернуться проти вас</b>: не виводити активи, не проводити збори з порушенням процедури, не звільняти працівників «для тиску». У корпоративних справах суд дивиться на поведінку сторін протягом усього конфлікту.</p>`,
