        html: `<p>Плутанина тут коштує часу. Ліцензування регулює Закон № 222-VIII, а <strong>дозвільну систему</strong> — окремий Закон «Про дозвільну систему у сфері господарської діяльності» № 2806-IV.</p>
<p>Один бізнес може одночасно потребувати ліцензії на вид діяльності, дозволу на конкретний об’єкт і погодження від галузевого органу. Це три різні процедури з різними строками й органами, і наявність однієї не замінює іншої.</p>
<p>Окремо стоїть <strong>ліцензування зовнішньоекономічних операцій</strong>: переліки товарів, експорт та імпорт яких підлягає ліцензуванню, і квоти затверджуються урядом <strong>щороку окремою постановою</strong>. Те, що торік не потребувало ліцензії, цьогоріч може її потребувати.</p>`,
