        html: `<p>Термінологія прийшла з англомовної практики, і її варто розуміти однозначно, бо саме в ній виникає більшість спорів.</p>
<table>
<thead><tr><th>Термін</th><th>Що означає</th><th>Типове значення</th></tr></thead>
<tbody>
<tr><td><b>Grant</b> (надання)</td><td>момент, коли людина отримує опціон - право, а не саму частку</td><td>дата підписання документів</td></tr>
<tr><td><b>Vesting</b> (визрівання)</td><td>поступове набуття права реалізувати опціон - за часом і/або за досягненням показників</td><td>4 роки, щомісячно або щоквартально</td></tr>
<tr><td><b>Cliff</b> (поріг)</td><td>початковий період, до спливу якого не визріває нічого</td><td>1 рік (після нього одразу визріває 25 %)</td></tr>
<tr><td><b>Strike price</b> (ціна реалізації)</td><td>ціна, за якою можна придбати частку при реалізації опціону</td><td>номінал, символічна або оцінка на дату надання</td></tr>
<tr><td><b>Exercise</b> (реалізація)</td><td>момент, коли людина фактично купує частку</td><td>часто - лише при виході (exit)</td></tr>
<tr><td><b>Exercise window</b></td><td>строк, протягом якого можна реалізувати визрілий опціон після звільнення</td><td>від 30 днів до кількох років</td></tr>
<tr><td><b>Good leaver / bad leaver</b></td><td>різні наслідки залежно від причини звільнення</td><td>good - зберігає визріле; bad - втрачає все</td></tr>
</tbody>
</table>
<p>Типовий графік: <b>4 роки з cliff один рік</b>. Людина, яка пішла через 11 місяців, не отримує нічого. Після року визріває 25 %, далі — щомісяця або щокварталу рівними частинами до повних 100 % на четвертий рік.</p>
<p>Окремо варто продумати <b>акселерацію</b> — ситуацію, коли опціон визріває достроково. Класичні випадки: продаж компанії (single trigger) або продаж компанії плюс звільнення працівника новим власником (double trigger). Якщо цього в документах немає, при продажу бізнесу команда може залишитися з невизрілими опціонами, і саме тоді програма перетворюється на джерело конфлікту замість мотивації.</p>`,
