        id: "s5",
        h2: "Правова база: на чому це тримається в Україні",
        html: `<p>Головне, що треба прийняти з самого початку: <b>окремої законодавчої регуляції опціонних програм в Україні немає</b>. Немає «закону про ESOP», немає спеціального податкового режиму для опціонів, немає типової форми. Усе будується з наявних інструментів цивільного й корпоративного права.</p>
<p>Що дає чинне право:</p>
<ul>
<li><b>Корпоративний договір</b> — ст. 7 Закону «Про товариства з обмеженою та додатковою відповідальністю». Це договір, за яким учасники зобов'язуються реалізовувати свої права та повноваження певним чином або утримуватися від їх реалізації. Укладається в <b>письмовій формі</b>, може бути оплатним або безоплатним. <b>Додатковими сторонами можуть бути саме товариство та треті особи</b> — саме ця норма (у редакції Закону № 2465-IX) і робить можливим включення працівника, який ще не є учасником, до корпоративного договору. Договір, який не відповідає цим вимогам, є <b>нікчемним</b>.</li>
<li><b>Ключова норма для опціонів</b> — ч. 3 ст. 7: корпоративний договір може передбачати <b>умови або порядок визначення умов, на яких учасник має право або зобов'язаний купити або продати частку</b> у статутному капіталі (її частину), а також визначати випадки, коли таке право або обов'язок виникає. Це і є юридичний каркас опціону.</li>
<li><b>Конфіденційність</b> — ч. 5 ст. 7: зміст корпоративного договору не підлягає розкриттю і є конфіденційним, якщо інше не встановлено законом або договором. Для опціонної програми це важливо: умови для різних людей зазвичай різні.</li>
<li><b>Безвідклична довіреність з корпоративних прав</b> — ст. 8 Закону про ТОВ. Інструмент, який забезпечує виконання зобов'язань за корпоративним договором: її не можна відкликати до спливу строку або настання обставин, визначених договором.</li>
<li><b>Переважне право</b> — ст. 20 Закону про ТОВ. Це головна технічна перешкода для передачі частки працівникові: інші учасники мають переважне право на її придбання. Статутом можна встановити інший порядок реалізації переважного права або <b>взагалі його виключити</b> — і для компанії, яка планує опціонну програму, це треба зробити <b>заздалегідь</b>, через <a href="/blog/zminy-do-statutu-tov/">зміни до статуту</a>, а не в момент першої реалізації опціону.</li>
<li><b>Режим Дія Сіті</b> — Закон «Про стимулювання розвитку цифрової економіки в Україні» від 15 липня 2021 року № 1667-IX. Він не створює окремого режиму опціонів, але гіг-контракт як гнучка конструкція дозволяє включати умови довгострокової винагороди, а сам статус резидента дає пільгове оподаткування винагороди спеціалістів.</li>
</ul>
<p>Обмеження, про яке варто знати: за ч. 4 ст. 7 Закону про ТОВ корпоративний договір, яким встановлюється <b>обов'язок учасників забезпечити голосування згідно з вказівками органів управління товариства</b>, є нікчемним. Тобто не можна через опціонну програму зробити працівників «керованими голосами» директора.</p>`,
