        html: `<ul>
<li><b>Обіцянка на словах або в листі.</b> «Ти отримаєш 2 % коли вийдемо на інвестиційний раунд» без документа — це не опціон. Юридично це не створює нічого, а психологічно створює очікування, і в момент виходу компанія отримує конфлікт або позов про обіцяне.</li>
<li><b>Відсутність сценаріїв звільнення.</b> Найчастіша й найдорожча помилка. Людина пішла — частка залишилася в неї, зв'язку з компанією немає, а вона блокує рішення або з'являється перед продажем бізнесу.</li>
<li><b>Переважне право не виключене статутом.</b> Програма затверджена, перший опціон визрів, а передати частку не можна без процедури з переважним правом інших учасників. Статут треба готувати до запуску програми.</li>
<li><b>Ігнорування розмивання.</b> Працівникові обіцяли 1 %, увійшов інвестор, емісія розмила частку до 0,6 % — і ніде не зафіксовано, чи це допустимо. Правило перерахунку має бути в документах.</li>
<li><b>Немає drag-along.</b> Міноритарій із 0,5 % здатен заблокувати продаж бізнесу або вимагати непропорційну ціну.</li>
<li><b>Опціон замість зарплати.</b> Крім мотиваційного провалу це ще й порушення трудового законодавства: винагорода за працю виплачується грошима у встановлені строки.</li>
<li><b>Непрорахована оцінка у фантомних акціях.</b> Якщо методика визначення вартості не узгоджена письмово, спір про суму виплати виникає саме тоді, коли гроші вже на столі.</li>
<li><b>Податковий сюрприз при реалізації.</b> Придбання частки за символічну ціну може створити оподатковуваний дохід у момент, коли людина ще нічого не заробила. Етап реалізації потрібно прораховувати окремо від етапу продажу.</li>
</ul>
<p>Загальний принцип простий: опціонна програма — це <b>не HR-документ, а корпоративна конструкція</b>. Вона торкається статуту, структури власності, податків і трудових відносин одночасно, і кожен із цих шарів має бути узгоджений з іншими до того, як першій людині щось пообіцяли.</p>`,
