    faq: [
      { q: "Коли потрібен дозвіл АМКУ на концентрацію?", a: "Коли вартісні показники учасників концентрації — сукупні активи та дохід від реалізації, окремо в Україні та загалом — перевищують порогові значення, встановлені законом. Конкретні суми варто перевіряти за чинною редакцією Закону «Про захист економічної конкуренції», оскільки аналітичні публікації дають різні цифри." },
      { q: "Чи можна закрити угоду до отримання дозволу?", a: "Ні. Концентрація, яка потребує дозволу, забороняється до його отримання. Тому в договорі має бути відкладальна умова — закриття лише після отримання дозволу АМКУ." },
      { q: "Скільки розглядається заява про концентрацію?", a: "Звичайний розгляд — близько 45 календарних днів, спрощена процедура у визначених законом випадках — близько 25 днів. Це строки розгляду; підготовка заяви з економічними даними зазвичай займає більше." },
      { q: "Який максимальний штраф АМКУ?", a: "До 10 % доходу (виручки) за останній звітний рік, що передував року накладення штрафу, а якщо незаконно одержаний прибуток перевищує 10 % доходу — до потрійного розміру такого прибутку. База — дохід, а не прибуток." },
      { q: "Який штраф за концентрацію без дозволу?", a: "До 5 % доходу (виручки) за останній звітний рік." },
      { q: "Що буде, якщо не відповісти на запит АМКУ?", a: "Неподання інформації або подання недостовірної інформації карається штрафом до 1 % доходу. Це самостійне порушення незалежно від результату основної справи." },
      { q: "Чи є домінування на ринку порушенням?", a: "Саме домінуюче становище порушенням не є. Порушенням є зловживання ним — наприклад, встановлення цін, які неможливо було б встановити за умов конкуренції, або відмова від постачання без об’єктивних причин." },
    ],
    related: ["etapy-uhody-ma", "dozvil-amku-na-kontsentratsiyu", "zakhyst-komertsiynoyi-tayemnytsi"],
