        html: `<p>Кінцевий бенефіціарний власник — це <b>фізична особа</b>, яка має вирішальний вплив на діяльність компанії. Ключове слово тут «фізична»: КБВ ніколи не може бути юридичною особою, скільки б рівнів володіння не було в структурі.</p>
<p>Мета вимоги проста — зробити прозорим, хто насправді стоїть за бізнесом. Це вимога законодавства про запобігання відмиванню доходів, і вона стосується практично всіх юридичних осіб, а не лише фінансових установ.</p>
<p>На практиці відомості про КБВ перевіряють банки при відкритті рахунку, контрагенти при укладенні великих договорів і замовники в публічних закупівлях. Відсутність або невідповідність даних блокує ці процеси швидше, ніж настає формальна відповідальність.</p>`,
