<p>Виникає замкнене коло, яке треба розривати правильною послідовністю: компанію спершу реєструють, потім вона отримує дозвіл, і лише після цього іноземець оформлюється на посаду. На перехідний період директором зазвичай призначають громадянина України.</p>
