        id: "s1",
        h2: "Що таке громадська організація",
        html: `<p>Громадська організація — це добровільне об’єднання фізичних осіб для здійснення та захисту прав і свобод, задоволення суспільних інтересів. Вона діє на підставі закону про громадські об’єднання і не має на меті одержання прибутку.</p>
<p>Ключова відмінність від бізнесу — <b>відсутність власників</b>. У ГО немає засновників із частками, немає статутного капіталу, немає дивідендів. Ті, хто створив організацію, не набувають на неї майнових прав, а майно ГО не може бути розподілене між членами.</p>
<p>Це варто розуміти до реєстрації. Люди нерідко створюють ГО, розраховуючи на «неоподатковувану» модель бізнесу, і потім стикаються з тим, що вивести кошти з організації законно неможливо.</p>
<p>ГО може існувати у двох режимах: <b>зі статусом юридичної особи</b> або <b>без нього</b>. Другий варіант простіший — подається повідомлення про утворення, — але така організація не має рахунку, не укладає договорів від власного імені й не може отримувати гранти. Практично в переважній більшості випадків потрібен саме статус юридичної особи.</p>`,
